function Restore-FromBase64Chunks {
    [CmdletBinding()]
    param (
        [Parameter(Mandatory = $true)]
        [string[]] $Chunks,

        [Parameter(Mandatory = $true)]
        [string] $OutputFile
    )

    $Base64 = $Chunks -join ""
    [byte[]]$CompressedBytes = [Convert]::FromBase64String($Base64)

    # Decompress
    $InputStream = [System.IO.MemoryStream]::new($CompressedBytes)
    $GzipStream = [System.IO.Compression.GzipStream]::new($InputStream, [IO.Compression.CompressionMode]::Decompress)
    $OutputStream = [System.IO.MemoryStream]::new()
    $Buffer = [byte[]]::new(4096)

    while ($true) {
        $read = $GzipStream.Read($Buffer, 0, $Buffer.Length)
        if ($read -le 0) { break }
        $OutputStream.Write($Buffer, 0, $read)
    }

    $GzipStream.Dispose()
    $InputStream.Dispose()

    $OutputBytes = $OutputStream.ToArray()
    $OutputStream.Dispose()
    $realOutfile=Get-UniqueFilePath $OutputFile
    [IO.File]::WriteAllBytes($realOutfile, $OutputBytes)
    return $realOutfile
}

function Restore-FileFromChunks {
    [CmdletBinding()]
    param ()

    
    $outputFile=Restore-FromBase64Chunks -Chunks $Base64Chunks -OutputFile "$ENV:Temp\recovered-matrix.mp4"
    $RecoveredHash = (Get-FileHash -Path "$outputFile" -Algorithm MD5).Hash

    if($RecoveredHash -ne "78042C8D562879105299458FD377A0CD"){
        Write-Host "Invalid Hash!" -f DarkRed
        return $Null
    }

    #Write-Host "File Recovered Successfully! "$outputFile"" -f DarkGreen
    
    return $outputFile
}

function Test-RestoreBinary {
    [CmdletBinding()]
    param ()


    [string]$Title="test"
    [string]$Url = Restore-FileFromChunks
    #Write-Host "reading "$Url"" -f DarkGray
    $MediaPlayer = New-Object System.Windows.Controls.MediaElement
    $MediaPlayer.Height = "742"
    $MediaPlayer.Width = "480"
    $MediaPlayer.Source = $Url

    Show-MessageBox -Content $MediaPlayer -Title $Title -ContentBackground "Gray" -ContentTextForeground "Black" -TitleTextForeground "Black" -TitleBackground "Gray" -ButtonTextForeground "Red"


    $MediaPlayer.LoadedBehavior = "Manual"
    $MediaPlayer.Stop()

    remove-item -Path "$Url" -Force
}

Test-RestoreBinary 

